-- Generated by scripts/promote-migrations.mjs from supabase/design/migrations/023_match_cancellation_and_atomic_lineup_save.sql
-- Do not edit by hand: the guard re-derives this file and fails on drift.

-- Phase 4 match workflow reliability and scheduled-match cancellation.
--
-- Saves both lineups in one database transaction so either both sides persist or
-- neither does. Empty side drafts are allowed; complete lineup limits are still
-- enforced by the existing submit-time validator. A scheduled match may be
-- cancelled only before its workflow/revision history begins; cancellation is
-- retained on the match and in the audit log rather than deleting history.

begin;

alter table public.real_matches
  add column cancelled_at timestamptz,
  add column cancelled_by uuid,
  add column cancel_reason text,
  add constraint real_matches_cancelled_by_fkey
    foreign key (league_id, cancelled_by) references public.league_members(league_id, user_id) on delete restrict,
  add constraint real_matches_cancel_fields_check check (
    (cancelled_at is null and cancelled_by is null and cancel_reason is null)
    or (cancelled_at is not null and cancelled_by is not null
        and cancel_reason is not null and length(btrim(cancel_reason)) between 1 and 500)
  );

-- Draft lineups may be empty or incomplete while an Organizer builds them.
-- Completeness and exact starter counts are checked at submission, not save.
create or replace function public.ff_match_set_lineup(
  p_league uuid, p_revision uuid, p_team uuid, p_players jsonb)
returns jsonb
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare r public.match_revisions; v_lineup public.real_match_lineups; item jsonb;
begin
  select * into r from public.match_revisions where league_id=p_league and id=p_revision;
  if not found then raise exception 'revision not found' using errcode='42501'; end if;
  if not (ff_private.is_leader(p_league) or ff_private.is_match_organizer(p_league,r.match_id)) then
    raise exception 'not the organizer of this match' using errcode='42501';
  end if;
  if r.state<>'draft' then raise exception 'revision is no longer editable' using errcode='23514'; end if;
  if exists(select 1 from public.real_matches where league_id=p_league and id=r.match_id and cancelled_at is not null) then
    raise exception 'cancelled matches cannot be edited' using errcode='23514';
  end if;
  if p_players is null or jsonb_typeof(p_players)<>'array' then
    raise exception 'lineup players must be an array' using errcode='23514';
  end if;
  if exists(select 1 from jsonb_array_elements(p_players) as row_data(entry) where coalesce(entry->>'eligibility_kind','market')<>'market') then
    raise exception 'new lineup assignments must come from this league market' using errcode='23514';
  end if;
  select * into v_lineup from public.real_match_lineups where league_id=p_league and revision_id=p_revision and team_id=p_team;
  if not found then
    insert into public.real_match_lineups(league_id,match_id,revision_id,team_id)
    values(p_league,r.match_id,p_revision,p_team) returning * into v_lineup;
  else
    delete from public.real_match_lineup_players where league_id=p_league and revision_id=p_revision and lineup_id=v_lineup.id;
  end if;
  for item in select * from jsonb_array_elements(p_players) loop
    insert into public.real_match_lineup_players(league_id,revision_id,lineup_id,player_id,selection,actual_position,eligibility_kind,eligibility_evidence)
    values(p_league,p_revision,v_lineup.id,(item->>'player_id')::uuid,item->>'selection',item->>'actual_position','market',
      coalesce(item->'eligibility_evidence','{}'::jsonb));
  end loop;
  perform ff_private.audit(p_league,'lineup_draft_set','match',r.match_id,
    jsonb_build_object('revision',p_revision,'team',p_team,'players',jsonb_array_length(p_players)));
  return jsonb_build_object('lineup_id',v_lineup.id,'players',jsonb_array_length(p_players));
end $$;

create or replace function public.ff_match_save_lineups(
  p_league uuid, p_revision uuid, p_team_a_players jsonb, p_team_b_players jsonb)
returns jsonb
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare r public.match_revisions; m public.real_matches%rowtype; saved_a jsonb; saved_b jsonb;
begin
  select * into r from public.match_revisions where league_id=p_league and id=p_revision;
  if not found then raise exception 'revision not found' using errcode='42501'; end if;
  -- Match first, then revision, matching the existing trigger lock order.
  select * into m from public.real_matches where league_id=p_league and id=r.match_id for update;
  if not found then raise exception 'match not found' using errcode='42501'; end if;
  select * into r from public.match_revisions where league_id=p_league and id=p_revision for update;
  if not found then raise exception 'revision not found' using errcode='42501'; end if;
  if m.cancelled_at is not null then raise exception 'cancelled matches cannot be edited' using errcode='23514'; end if;
  if p_team_a_players is null or jsonb_typeof(p_team_a_players)<>'array'
     or p_team_b_players is null or jsonb_typeof(p_team_b_players)<>'array' then
    raise exception 'both lineup selections must be arrays' using errcode='23514';
  end if;
  if jsonb_array_length(p_team_a_players)>m.starters_per_side+m.max_substitutes
     or jsonb_array_length(p_team_b_players)>m.starters_per_side+m.max_substitutes then
    raise exception 'lineup exceeds the configured player limit' using errcode='23514';
  end if;
  -- These calls are part of this RPC transaction. Any authorization, eligibility,
  -- duplicate-player, format, or persistence error rolls back both teams' saves.
  saved_a:=public.ff_match_set_lineup(p_league,p_revision,m.team_a_id,p_team_a_players);
  saved_b:=public.ff_match_set_lineup(p_league,p_revision,m.team_b_id,p_team_b_players);
  return jsonb_build_object('revision_id',p_revision,'team_a',saved_a,'team_b',saved_b,'saved',true);
end $$;

-- Once cancellation is recorded, an unopened scheduled match cannot acquire a
-- revision and thereby re-enter the workflow.
create or replace function public.ff_match_open_revision(p_league uuid, p_match uuid)
returns jsonb
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare v public.match_revisions; v_ver integer; m public.real_matches;
begin
  select * into m from public.real_matches where league_id=p_league and id=p_match for update;
  if not found then raise exception 'match not found' using errcode='42501'; end if;
  if not (ff_private.is_leader(p_league) or ff_private.is_match_organizer(p_league,p_match)) then
    raise exception 'not the organizer of this match' using errcode='42501';
  end if;
  if m.cancelled_at is not null then raise exception 'cancelled matches cannot be opened' using errcode='23514'; end if;
  select coalesce(max(version),0)+1 into v_ver from public.match_revisions where league_id=p_league and match_id=p_match;
  insert into public.match_revisions(league_id,match_id,version,match_snapshot)
  values(p_league,p_match,v_ver,jsonb_build_object('starts_at',m.starts_at,'venue',m.venue,'team_a_id',m.team_a_id,
    'team_b_id',m.team_b_id,'starters_per_side',m.starters_per_side,'max_substitutes',m.max_substitutes))
  returning * into v;
  return jsonb_build_object('id',v.id,'version',v.version,'state',v.state);
end $$;

create or replace function public.ff_match_cancel(p_league uuid,p_match uuid,p_reason text)
returns jsonb
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare m public.real_matches%rowtype; actor uuid:=ff_private.current_actor_id();
begin
  select * into m from public.real_matches where league_id=p_league and id=p_match for update;
  if not found then raise exception 'match not found' using errcode='42501'; end if;
  if not (ff_private.is_leader(p_league) or ff_private.is_match_organizer(p_league,p_match)) then
    raise exception 'only the Leader or assigned active Organizer can cancel this match' using errcode='42501';
  end if;
  if m.cancelled_at is not null then
    return jsonb_build_object('id',m.id,'cancelled',true,'cancelled_at',m.cancelled_at,'reason',m.cancel_reason);
  end if;
  if p_reason is null or length(btrim(p_reason)) not between 1 and 500 then
    raise exception 'a cancellation reason of 1–500 characters is required' using errcode='23514';
  end if;
  if exists(select 1 from public.match_revisions where league_id=p_league and match_id=p_match) then
    raise exception 'a match with workflow history cannot be cancelled here' using errcode='23514';
  end if;
  update public.real_matches set cancelled_at=now(),cancelled_by=actor,cancel_reason=btrim(p_reason)
    where league_id=p_league and id=p_match returning * into m;
  perform ff_private.audit(p_league,'match_cancelled','match',p_match,
    jsonb_build_object('cancelled_at',m.cancelled_at,'reason',m.cancel_reason));
  return jsonb_build_object('id',m.id,'cancelled',true,'cancelled_at',m.cancelled_at,'reason',m.cancel_reason);
end $$;

-- Preserve the reviewed member-scoped read model, adding the cancellation state.
create or replace function public.ff_matches(p_league uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
  perform ff_private.require_member(p_league);
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',m.id,'gameweek_id',m.gameweek_id,'starts_at',m.starts_at,'venue',m.venue,
      'team_a_id',m.team_a_id,'team_a',ta.name,'team_b_id',m.team_b_id,'team_b',tb.name,
      'organizer_id',m.organizer_id,'starters_per_side',m.starters_per_side,'max_substitutes',m.max_substitutes,
      'is_cancelled',(m.cancelled_at is not null),'cancelled_at',m.cancelled_at,'cancel_reason',m.cancel_reason,
      'revision_id',r.id,'revision_version',r.version,'revision_state',r.state,
      'team_a_score',official_revision.team_a_score,'team_b_score',official_revision.team_b_score,
      'is_official',(o.id is not null),'official_result_id',o.id,'official_revision_id',o.revision_id,
      'finalized_by',o.finalized_by,'finalized_at',o.finalized_at,
      'has_pending_lineup',exists(select 1 from public.match_submissions s where s.league_id=m.league_id and s.match_id=m.id and s.kind='lineup'
        and not exists(select 1 from public.match_approvals a where a.league_id=s.league_id and a.submission_id=s.id)),
      'has_pending_result',exists(select 1 from public.match_submissions s where s.league_id=m.league_id and s.match_id=m.id and s.kind='result'
        and not exists(select 1 from public.match_approvals a where a.league_id=s.league_id and a.submission_id=s.id)),
      'events',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'type',e.event_type,'minute',e.minute,'quantity',e.quantity,
        'player_id',e.player_id,'player_name',pp.display_name,'related_player_id',e.related_player_id) order by e.minute nulls last)
        from public.match_events e join public.player_profiles pp on pp.league_id=e.league_id and pp.id=e.player_id
        where e.league_id=m.league_id and e.revision_id=coalesce(o.revision_id,r.id)),'[]'::jsonb),
      'history',coalesce((select jsonb_agg(jsonb_build_object(
        'revision_id',v.id,'version',v.version,'state',v.state,'team_a_score',v.team_a_score,'team_b_score',v.team_b_score,
        'correction',(select jsonb_build_object('reason',c.reason,'actor_id',c.actor_id,'created_at',c.created_at)
          from public.match_corrections c left join public.match_correction_attempts ca on ca.league_id=c.league_id and ca.correction_id=c.id
          where c.league_id=v.league_id and c.match_id=v.match_id
            and (ca.draft_revision_id=v.id or ca.draft_revision_id=v.based_on_lineup_revision_id or c.draft_revision_id=v.id)
          order by ca.attempt_no desc limit 1),
        'events',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'type',e.event_type,'minute',e.minute,'quantity',e.quantity,
          'player_id',e.player_id,'player_name',(select pp.display_name from public.player_profiles pp where pp.league_id=e.league_id and pp.id=e.player_id),
          'related_player_id',e.related_player_id) order by e.minute nulls last) from public.match_events e where e.league_id=v.league_id and e.revision_id=v.id),'[]'::jsonb),
        'submissions',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'kind',s.kind,'submitted_by',s.submitted_by,'submitted_at',s.submitted_at,
          'approval',(select jsonb_build_object('id',a.id,'decision',a.decision,'reason',a.reason,'reviewed_by',a.reviewed_by,'reviewed_at',a.reviewed_at,
            'finalized_by',case when s.kind='result' and a.decision='approved' then a.reviewed_by else null end,
            'finalized_at',case when s.kind='result' and a.decision='approved' then a.reviewed_at else null end)
            from public.match_approvals a where a.league_id=s.league_id and a.submission_id=s.id)) order by s.submitted_at)
          from public.match_submissions s where s.league_id=v.league_id and s.revision_id=v.id),'[]'::jsonb),
        'lineups',coalesce((select jsonb_agg(jsonb_build_object('team_id',ln.team_id,'players',coalesce(
          (select jsonb_agg(jsonb_build_object('player_id',lp.player_id,'name',pp.display_name,'selection',lp.selection,'actual_position',lp.actual_position)
            order by lp.selection,pp.display_name) from public.real_match_lineup_players lp join public.player_profiles pp
            on pp.league_id=lp.league_id and pp.id=lp.player_id where lp.league_id=ln.league_id and lp.lineup_id=ln.id),'[]'::jsonb)) order by ln.team_id)
          from public.real_match_lineups ln where ln.league_id=v.league_id and ln.revision_id=v.id),'[]'::jsonb)
      ) order by v.version desc) from public.match_revisions v where v.league_id=m.league_id and v.match_id=m.id),'[]'::jsonb)
    ) order by m.starts_at desc)
    from public.real_matches m
    join public.real_football_teams ta on ta.league_id=m.league_id and ta.id=m.team_a_id
    join public.real_football_teams tb on tb.league_id=m.league_id and tb.id=m.team_b_id
    left join lateral (select v0.* from public.match_revisions v0 where v0.league_id=m.league_id and v0.match_id=m.id order by v0.version desc limit 1) r on true
    left join lateral (select o0.* from public.official_match_results o0 where o0.league_id=m.league_id and o0.match_id=m.id and o0.is_current limit 1) o on true
    left join public.match_revisions official_revision on official_revision.league_id=o.league_id and official_revision.id=o.revision_id
    where m.league_id=p_league
  ),'[]'::jsonb);
end $$;

-- These are additive client RPCs. Restrict execute to authenticated and keep the
-- standard function owner used by all trusted workflow helpers.
do $$
begin
  if exists(select 1 from pg_roles where rolname='ff_migration_owner') then
    alter function public.ff_match_save_lineups(uuid,uuid,jsonb,jsonb) owner to ff_migration_owner;
    alter function public.ff_match_cancel(uuid,uuid,text) owner to ff_migration_owner;
  end if;
end $$;
revoke all on function public.ff_match_save_lineups(uuid,uuid,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.ff_match_save_lineups(uuid,uuid,jsonb,jsonb) to authenticated;
revoke all on function public.ff_match_cancel(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.ff_match_cancel(uuid,uuid,text) to authenticated;

commit;
